namespace sv_44d180bbc748405ba9d019e56fb283ce.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_44d180bbc748405ba9d019e56fb283ce.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var isCompleted = CompletedSteps.Contains(stepIndex);
            var isCurrent = stepIndex == CurrentStep;
            var cssClass = isCurrent ? "step current" : isCompleted ? "step completed" : "step future";

            <li class="@cssClass">
                @if (isCompleted && !isCurrent)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <span class="step-content">
                        <span class="step-icon">@(stepIndex + 1)</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    };
}

@namespace sv_44d180bbc748405ba9d019e56fb283ce.Components.Pages.Apply

<div class="step-panel">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" class="form-control" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" @bind="Address" @bind:event="oninput" class="form-control" />
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-summary">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ValidationError;
    private string? EmailError;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ValidationError = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ValidationError = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isEmailValid = await ValidateEmail(Email);
            if (!isEmailValid)
            {
                EmailError = "Please enter a valid email address.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
        }
        finally
        {
            IsValidating = false;
        }
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

@namespace sv_44d180bbc748405ba9d019e56fb283ce.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company *</label>
            <input type="text" value="@Entry.Company" @onchange="e => Update(e, nameof(Entry.Company))" class="form-control" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title" @onchange="e => Update(e, nameof(Entry.Title))" class="form-control" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => Update(e, nameof(Entry.StartDate))" class="form-control" />
        </div>
        <div class="form-group">
            <label>
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentToggle" />
                Currently working here
            </label>
            @if (!IsCurrent)
            {
                <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="e => Update(e, nameof(Entry.EndDate))" class="form-control" />
            }
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="e => Update(e, nameof(Entry.Description))" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && Entry.IsCurrent;

    private async Task Update(ChangeEventArgs e, string field)
    {
        var updated = field switch
        {
            nameof(Entry.Company) => Entry with { Company = e.Value?.ToString() ?? "" },
            nameof(Entry.Title) => Entry with { Title = e.Value?.ToString() ?? "" },
            nameof(Entry.StartDate) => Entry with { StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : Entry.StartDate },
            nameof(Entry.EndDate) => Entry with { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null },
            nameof(Entry.Description) => Entry with { Description = e.Value?.ToString() ?? "" },
            _ => Entry
        };
        await OnChanged.InvokeAsync(updated);
    }

    private async Task HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        await OnChanged.InvokeAsync(updated);
    }

    public record WorkEntryModel
    {
        public string Company { get; init; } = "";
        public string Title { get; init; } = "";
        public DateTime StartDate { get; init; } = DateTime.Today;
        public DateTime? EndDate { get; init; }
        public string Description { get; init; } = "";
        public bool IsCurrent { get; init; }
    }
}

@namespace sv_44d180bbc748405ba9d019e56fb283ce.Components.Pages.Apply

<div class="step-panel">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnChanged="@(updated => HandleEntryChanged(index, updated))"
                       OnRemove="@(() => RemoveEntry(index))" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-summary">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryForm.WorkEntryModel> Entries { get; set; } = new() { new() };
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryForm.WorkEntryModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private void HandleEntryChanged(int index, WorkEntryForm.WorkEntryModel updated)
    {
        Entries[index] = updated;
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryForm.WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ValidationError = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ValidationError = "Each position must have at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}

@namespace sv_44d180bbc748405ba9d019e56fb283ce.Components.Pages.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Entry.Name" @onchange="e => Update(e, nameof(Entry.Name))" class="form-control" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Entry.Relationship" @onchange="e => Update(e, nameof(Entry.Relationship))" class="form-control" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email" @onchange="e => Update(e, nameof(Entry.Email))" class="form-control" />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Entry.Phone" @onchange="e => Update(e, nameof(Entry.Phone))" class="form-control" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<ReferenceModel> OnChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    private async Task Update(ChangeEventArgs e, string field)
    {
        var updated = field switch
        {
            nameof(Entry.Name) => Entry with { Name = e.Value?.ToString() ?? "" },
            nameof(Entry.Relationship) => Entry with { Relationship = e.Value?.ToString() ?? "" },
            nameof(Entry.Email) => Entry with { Email = e.Value?.ToString() ?? "" },
            nameof(Entry.Phone) => Entry with { Phone = e.Value?.ToString() ?? "" },
            _ => Entry
        };
        await OnChanged.InvokeAsync(updated);
    }

    public record ReferenceModel
    {
        public string Name { get; init; } = "";
        public string Relationship { get; init; } = "";
        public string Email { get; init; } = "";
        public string Phone { get; init; } = "";
    }
}

@namespace sv_44d180bbc748405ba9d019e56fb283ce.Components.Pages.Apply

<div class="step-panel">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@References[index]"
                       Index="index"
                       CanRemove="@(References.Count > 2)"
                       OnChanged="@(updated => HandleReferenceChanged(index, updated))"
                       OnRemove="@(() => RemoveReference(index))" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-summary">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = new() { new(), new() };
    [Parameter, EditorRequired] public EventCallback<List<ReferenceForm.ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private void HandleReferenceChanged(int index, ReferenceForm.ReferenceModel updated)
    {
        References[index] = updated;
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceForm.ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ValidationError = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ValidationError = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }
}

@namespace sv_44d180bbc748405ba9d019e56fb283ce.Components.Pages.Apply

<div class="step-panel">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter"
                  class="form-control cover-letter-textarea"
                  rows="12"
                  maxlength="@MaxLength"
                  @bind="CoverLetter"
                  @bind:event="oninput"></textarea>
        <span class="char-count">@CoverLetter.Length / @MaxLength characters</span>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-summary">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private string? ValidationError;

    private async Task HandleNext()
    {
        ValidationError = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ValidationError = "Please write a cover letter.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_44d180bbc748405ba9d019e56fb283ce.Components.Pages.Apply

<div class="step-panel">
    <h2>Review & Submit</h2>
    <p class="step-description">Please review your application before submitting.</p>

    @if (IsSubmitted)
    {
        <div class="confirmation-panel">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application has been received. Your application ID is: <strong>@ApplicationId</strong></p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-section-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <small>@entry.StartDate.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />
                    <small>@r.Email | @r.Phone</small>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(SubmitError))
        {
            <div class="validation-summary">@SubmitError</div>
        }

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="OnBack">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoStep.PersonalInfoResult Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryForm.WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceForm.ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
